{
  "blocks": [
    {
      "kind": "dialogue",
      "text": "刘二叔咽下最后一口干粮，身子微微前倾，压低声音说道：“除了骨头摩擦，还有风声呜咽，像是有谁在哭。那声音断断续续的，就在老槐树根底下，听得人心里发毛。”",
      "speaker": "k1_person_刘二叔"
    }
  ],
  "choices": [
    {
      "action": "interact:ask",
      "targetId": "k1_person_刘二叔",
      "stake": "low",
      "purpose": "询问刘二叔：那哭声是男是女，听起来有多大年纪。",
      "anchor": 0
    },
    {
      "action": "interact:ask",
      "targetId": "k1_person_刘二叔",
      "stake": "low",
      "purpose": "询问刘二叔：除了哭声和骨头声，有没有闻到什么奇怪的味道。",
      "anchor": 0
    },
    {
      "action": "interact:decline",
      "targetId": "k1_person_刘二叔",
      "stake": "low",
      "purpose": "拒绝刘二叔：不想再听这些怪事，转身离开。",
      "anchor": 0
    }
  ],
